#!/usr/bin/env python3
"""Record pinned Leap Attack gaps and Double Throw shared-consumer integration contracts."""
from pathlib import Path
import hashlib,json,re
ROOT=Path(__file__).resolve().parents[1];STAGE=ROOT/'.local/class-skills';SOURCE=ROOT/'tools/reference/d2r-named-equipment/json'
tree=json.loads((STAGE/'d2moo-source-tree.json').read_text());assert tree['sha']=='0c0bbd1e6bef9181a3da1c046523af622a925416'
hashes={};blocks={}
def source(path):
 raw=(STAGE/'d2moo-pinned-source'/path).read_bytes();blob=next(v['sha'] for v in tree['tree'] if v['path']==path)
 assert hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()==blob
 hashes[path]=hashlib.sha256(raw).hexdigest();return raw.decode()
def block(text,name):
 m=re.search(r'^.*\b'+re.escape(name)+r'\([^;\n]*\)\s*\n\{',text,re.M);assert m,name
 end=text.index('{',m.start())+1;depth=1
 while depth:depth+=(text[end]=='{')-(text[end]=='}');end+=1
 blocks[name]=hashlib.sha256(text[m.start():end].encode()).hexdigest()
def row(table,key,value):return next({k:v for k,v in r.items() if v not in ('',None)} for r in json.loads((SOURCE/(table+'.json')).read_text()).values() if r.get(key)==value)
bar=source('source/D2Game/src/SKILLS/SkillBar.cpp');common=source('source/D2Common/src/D2Skills.cpp')
for text,name in [(bar,'SKILLS_SrvSt41_LeapAttack'),(bar,'SKILLS_SrvDo078_LeapAttack'),(bar,'SKILLS_FindLeapAttackTarget'),(common,'SKILLS_CheckIfCanLeapTo')]:block(text,name)
leap=dict(referenceVersion='3.3.93847',status='Individually deferred: modern do78 landing-nova emission/ordering is absent from the older engine source. Continue Double Throw; no substitute Leap knockback or invented nova enabled.',skill=row('skills','skill','Leap Attack'),missile=row('missiles','Missile','leapattack'),description=row('skilldesc','skilldesc','leap attack'),legacyCommit=tree['sha'],sourceHashes=hashes,reviewedBlockHashes=blocks,
 releasedPrimary=dict(url='https://news.blizzard.com/en-gb/article/23788293/diablo-ii-resurrected-patch-2-4-ladder-now-live',scope='Released2.4 confirms weapon-independent physical landing area,4.6-yard stated range, hard Leap synergy on both components,175% jump speed, minimum jump duration/height,10mana and adjacent-target leaps. Current pinned tables supply all numeric fields; PTR values are not substituted.'),
 established=['Leap Attack uses start41/do78/SQ14, two separate damage components, current mana10, minimum12 airborne frames and calc2=175. Weapon ED is200+30 per rank plus hard Leap10%; area base damage uses separate five tiers and the same hard synergy.','Legacy destination helper differs from Leap: target plus2 units along the direction, fallback free search with player-path mask and neighbor=false, then flying door|missile-barrier ray and town check. Old melee fallback is explicitly superseded by released adjacent-target leaps.','Legacy do78 follows landing with target search/weapon strike. Current srvmissilea leapattack is absent from that older body; modern creation count/directions/timing relative to weapon strike cannot be established from that body. Missile table do1/dmg7, velocity12/range12/init1/size1/nextdelay4 do not by themselves establish emission.'],
 reuse=['Reuse saved Leap flight/reservation/death/network/resource consumers after supplying distinct target geometry/weapon-specific SQ14 phases and current minimum12.','Reuse selected-hand/GearEffects prepared weapon hit for the primary strike. Area uses physical skill endpoints and existing shared ray/mitigation/delay consumers only once its emission/ordering contract is established. Do not pass mastery, critical, weapon damage, leech or on-strike procs into the weapon-independent area.'],
 unresolved=['Modern landing nova count/directions/creation phase/weapon-versus-area order; a64-ray Shout ring is a candidate reuse point, not established behavior.','Modern adjacent and ground targeting/range/destination/target-reacquisition changes and exact SQ14/IAS/WSM/FCR timing; old source cannot certify these changed branches.','Full source/native terrain, delayed-death area, gear/owner/snapshot/proc/dodge/client acceptance.'],assets={'effect':'Pending distinct Leap Attack jump/arc/weapon impact/physical landing wave and doubledamage1 presentation; keep separate from Leap knockback in effect register.','icon':'Pending talent-tree and hotkey icon in separate icon register.'})
(ROOT/'tools/reference/barbarian-leap-attack-preflight.json').write_text(json.dumps(leap,indent=2)+'\n')
throw=dict(referenceVersion='3.3.93847',status='Native Double Throw integration uses the recorded shared consumers; bounded source proof does not certify modern projectile/client parity.',skill=row('skills','skill','Double Throw'),evidence='tools/reference/double-throw-engine-evidence.json',reuse=['Native supported dual-equip/primary identity, scoped selected-hand damage/AR/IAS/mastery/gear and independent saved ammunition ledger.','Existing projectile critical/conservation/pierce path accepts untrained mastery; each hand releases/recovers/spends once per source event.','Existing ClassCombat input/held action/session clocks, accepted-movement and hit-recovery cancellation, GearEffects mitigation/typed damage/procs and NamedProjectiles collision/continuation.'],contracts=['SQ15 events at points5/9 are scheduled with ordinals0/1; server weapsel3 selects primary then secondary. Use attack rate with12-point cycle.','No srv-start: payment occurs after each successful do74, including failed quantity/allocation. Preserve the older ignored debit failure as an explicitly uncertain modern edge; do not infer one payment for the pair from the tooltip.','Current data: two throwing requirements, mana1 per do, AR20+10/rank, physical ED16+8/rank+8% per hard Double Swing point. Empty-ground releases are valid.'],limits=['Shared native NamedProjectiles still resolves a ray immediately with cosmetic travel. True source-timed missiles, released stat snapshots, moving-target collision and exact full modern damage/proc/RNG/owner/client parity remain pending. This is not an approved deviation.','Native dual-weapon IAS/WSM/SC cadence, low-mana/payment and quantity-zero/ethereal behavior remain acceptance work. Throwable potion and crafted/rune/material pairs lack adapters.'],assets={'effect':'Identified native0xF42 projectile/0x238 sound placeholders. Final per-weapon throwing flight/impact effects remain in effects register.','icon':'Separate pending Double Throw talent-tree/hotkey icon.'})
(ROOT/'tools/reference/barbarian-double-throw-preflight.json').write_text(json.dumps(throw,indent=2)+'\n')
print('Leap Attack source gap and Double Throw reuse/payment/event contracts recorded.')
